import os
import torch


class Config:
    # -------------------------------------------------------------------------
    # Paths
    # -------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    # Working directory for caching processed data and saving models
    WORKING_DIR = "./working/idea_33"
    SUBMISSION_DIR = "./submission"

    # Metadata files generated by the analysis script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Sample submission for formatting
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Model save path
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pt")

    # -------------------------------------------------------------------------
    # Reproducibility
    # -------------------------------------------------------------------------
    SEED = 42

    # -------------------------------------------------------------------------
    # Data Processing Hyperparameters
    # -------------------------------------------------------------------------
    # Atomic types present in the dataset
    ATOM_TYPES = ["Al", "Ga", "In", "O"]
    NUM_ATOM_TYPES = len(ATOM_TYPES)

    # Gaussian Density Field Parameters
    # Gamma controls the width of the Gaussian kernel: exp(-gamma * d^2)
    DENSITY_GAMMA = 1.0
    # Cutoff radius for calculating local densities (Angstroms)
    # Interactions beyond this distance are considered negligible for the density field
    DENSITY_CUTOFF = 6.0

    # -------------------------------------------------------------------------
    # Feature Dimensions
    # -------------------------------------------------------------------------
    # Atomic Stream Features:
    # 4 (One-Hot) + 3 (Centered Coords) + 1 (NN Dist) + 4 (Chemical Densities)
    ATOMIC_INPUT_DIM = 12

    # Global Stream Features:
    # 3 (Lattice Lens) + 3 (Lattice Angs) + 1 (Volume) + 1 (Density) + 1 (Total Atoms) + 3 (Stoichiometry)
    GLOBAL_INPUT_DIM = 12

    # -------------------------------------------------------------------------
    # Model Architecture
    # -------------------------------------------------------------------------
    # Atomic Stream Encoder (Wide MLP)
    ATOMIC_HIDDEN_DIM = 512
    ATOMIC_LAYERS = 3

    # Global Stream Encoder
    GLOBAL_HIDDEN_DIM = 256
    GLOBAL_LAYERS = 2

    # Fusion Head
    # The atomic embedding size after pooling (Mean + Max = 2 * ATOMIC_HIDDEN_DIM)
    # Plus the global embedding size
    FUSION_INPUT_DIM = (2 * ATOMIC_HIDDEN_DIM) + GLOBAL_HIDDEN_DIM
    FUSION_HIDDEN_DIMS = [512, 256, 128]

    # Regularization
    DROPOUT_RATE = 0.1
    USE_BATCH_NORM = True

    # Outputs
    OUTPUT_DIM = 2  # formation_energy_ev_natom, bandgap_energy_ev

    # -------------------------------------------------------------------------
    # Training Hyperparameters
    # -------------------------------------------------------------------------
    BATCH_SIZE = 64
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4
    NUM_EPOCHS = 200

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 20

    # Learning Rate Scheduler (ReduceLROnPlateau)
    SCHEDULER_FACTOR = 0.5
    SCHEDULER_PATIENCE = 5
    SCHEDULER_MIN_LR = 1e-6

    # -------------------------------------------------------------------------
    # Compute
    # -------------------------------------------------------------------------
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4  # For DataLoader

    # -------------------------------------------------------------------------
    # Caching
    # -------------------------------------------------------------------------
    # Names for cached files
    TRAIN_CACHE_FILE = "train_data.npz"
    VAL_CACHE_FILE = "val_data.npz"
    TEST_CACHE_FILE = "test_data.npz"
    SCALERS_CACHE_FILE = "scalers.npz"

    @classmethod
    def make_dirs(cls):
        """Ensure necessary directories exist."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
